extensibility-requirements.requirement:
      RosterStudentRow should accept optional render props for points and attendance cells.
      In Story 3-1, render placeholder text. In Stories 3-2/3-9, pass interactive components.

interface RosterStudentRowProps {
  student: RosterStudent;
  date: string;
  period: number | null;
  renderPointsCell?: (student: RosterStudent) => React.ReactNode;
  renderAttendanceCell?: (student: RosterStudent) => React.ReactNode;
}

      Establish updateStudentData pattern for instant UI feedback (used heavily in Story 3-2).

const updateStudentData = (placementId: string, updates: Partial<RosterStudent>) => {
  setStudents(prev => prev.map(s =>
    s.placement_id === placementId ? { ...s, ...updates } : s
  ));
};

